import{z as n,x as B,o as e,c as d,q as t,j as l,D as E,d as o,s as r,S as A}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"glitch token","description":"","frontmatter":{"title":"glitch token","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/glitch-tokens.md","filePath":"llm/glitch-tokens.md","lastUpdated":1791063341000}'),s={name:"llm/glitch-tokens.md"};function p(h,a,c,m,g,k){const i=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="glitch-token" tabindex="-1">glitch token <a class="header-anchor" href="#glitch-token" aria-label="Permalink to &quot;glitch token&quot;">​</a></h1><div class="epigraph"><p>词表里有一些符号几乎从未在预训练里以「被切出来」的方式出现，它们的嵌入停留在初始化附近，一旦被提示触发，模型会胡言乱语或泄露训练残渣。</p><footer>—— Rumbelow 与 Watkins 对 SolidGoldMagikarp 的观察；Land 与 Bartolo，Fishing for Magikarp</footer></div><p><a href="/llm/tokenizer-fertility">上一课</a>度量的是平均与分位的长度税。平均很健康时，仍可能存在一小组 id：它们在词表里合法，在模型语料的实际切分里却接近于零。本课不重讲 fertility 报表。缺口是这些欠训符号——glitch token——如何被词表算法制造出来，以及预训练工程如何在发版前把它们找掉或钉死。下一单元改数据配比，默认词表的这个病灶已经处理过。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/bpe-merge-rule">BPE</a> 的合并表在词表语料上长出符号 \\(x\\)；模型预训练用的是另一份混合物，且经过 <a href="/llm/web-clean-dedup">清洗去重</a>。若 \\(x\\) 只来自词表抽样里的一个站点模板，或来自 SentencePiece 的 unused 槽位，或来自 <a href="/llm/byte-fallback">字节回退</a> 符号的罕见组合，那么正向切分几乎从不产出 \\(x\\)。嵌入行只吃到极少梯度，范数、余弦邻居都会异常。Rumbelow 与 Watkins 在 GPT 系列里找到 <code>SolidGoldMagikarp</code> 一类 token，提示里单独放出它们会得到崩溃式输出。</p><p><span class="marginnote">BPE 就是从单个字符出发、反复把语料里最常见的相邻对合并成新符号的手段来切词；合并表长成什么样，完全由喂给它的那份词表语料决定。所以「词表里有这个 token」和「模型训练时见过它」是两回事——前者由 tokenizer 语料决定，后者由模型语料决定，两份语料对不上，洞就出现了。</span></p><p>这不是对齐阶段才有的幻觉，而是离散基底与训练测度的支撑集不一致。特殊 token 若在预训练从未插入，也会变成一类受控的「故意 glitch」，直到指令数据把它们热起来——那是后课的事。本课关注的是内容词表里的意外空洞。</p><h3 id="未使用槽与幽灵合并" tabindex="-1">未使用槽与幽灵合并 <a class="header-anchor" href="#未使用槽与幽灵合并" aria-label="Permalink to &quot;未使用槽与幽灵合并&quot;">​</a></h3><p>许多实现预留 dummy id，或把词表 pad 到 64 的倍数。这些行若随机初始化且从不出现，就是现成的 glitch。BPE 还可能焊出只在词表语料 n-gram 里存在的怪串，正则一改或清洗一变，模型语料再也不切出它们。Land 与 Bartolo 把「检测欠训 token」做成可自动跑的审计，而不是靠玩家扫词表。</p><p><span class="marginnote">glitch 与「低频词」不同。低频词仍按正确切分出现，只是次数少；glitch 是切分函数在模型测度上的支撑接近空，次数是零或接近零。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在冻结词表上，用模型预训练的真实加载器（同一正则、同一特殊符号规则）扫过一份有代表性的混合物，统计每个 id 的出现次数。低于阈值的 id 列入候选：再看嵌入范数、与均值的距离、解码成可读串是否像乱码或像爬虫残留。对确认的 glitch：可在推理侧拒绝单独生成、可在续训里用受控上下文把它们曝露出来、或在下次词表迭代里删除（删除会改 id，通常只允许未发版模型）。</p>',12)),(e(),l(A,null,{default:E(()=>[r(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCAN%5B%22%E7%9C%9F%E5%AE%9E%E5%8A%A0%E8%BD%BD%E5%99%A8%E6%89%AB%E4%BB%A3%E8%A1%A8%E6%80%A7%E6%B7%B7%E5%90%88%E7%89%A9%22%5D%20--%3E%20CNT%5B%22%E7%BB%9F%E8%AE%A1%E6%AF%8F%E4%B8%AA%20id%20%E5%87%BA%E7%8E%B0%E6%AC%A1%E6%95%B0%22%5D%0A%20%20CNT%20--%3E%20LOW%5B%22%E6%AC%A1%E6%95%B0%E6%8E%A5%E8%BF%91%E9%9B%B6%E7%9A%84%E5%80%99%E9%80%89%22%5D%0A%20%20LOW%20--%3E%20GEO%5B%22%E6%9F%A5%E5%B5%8C%E5%85%A5%E8%8C%83%E6%95%B0%E4%B8%8E%E9%82%BB%E5%B1%85%E6%98%AF%E5%90%A6%E5%BC%82%E5%B8%B8%22%5D%0A%20%20GEO%20--%3E%20TRG%5B%22%E4%B8%BB%E5%8A%A8%E8%A7%A6%E5%8F%91%EF%BC%9A%E5%8D%95%E7%8B%AC%E6%94%BE%E8%BF%9B%E6%8F%90%E7%A4%BA%22%5D%0A%20%20TRG%20--%3E%20OK%5B%22%E7%A8%B3%E5%AE%9A%20%E2%86%92%20%E5%8F%AA%E6%98%AF%E7%BD%95%E8%A7%81%E8%AF%8D%EF%BC%8C%E4%BF%9D%E7%95%99%22%5D%0A%20%20TRG%20--%3E%20BAD%5B%22%E5%8F%91%E6%95%A3%20%E2%86%92%20%E7%A1%AE%E8%AE%A4%20glitch%22%5D%0A%20%20BAD%20--%3E%20H1%5B%22%E6%8E%A8%E7%90%86%E4%BE%A7%E8%BF%87%E6%BB%A4%22%5D%0A%20%20BAD%20--%3E%20H2%5B%22%E7%BB%AD%E8%AE%AD%E5%8F%97%E6%8E%A7%E6%9B%9D%E9%9C%B2%22%5D%0A%20%20BAD%20--%3E%20H3%5B%22%E4%B8%8B%E4%B8%80%E4%BB%A3%E8%AF%8D%E8%A1%A8%E5%88%A0%E9%99%A4%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">直觉类比：词表像一本字典，里头收了几个从没人查过、也没人教过含义的生僻词条。平时没人念它们就相安无事；一旦有人在句子里说出这个词，读者只能瞎编——因为那个词对应的「含义向量」从训练第一天起就没被更新过。</span></p><p>不要用「把 glitch 从词表抹掉再重编号」修补已发布检查点。正确补丁是：推理过滤器 + 文档化 + 下一代词表在 <a href="/llm/tokenizer-training-corpus">词表语料</a> 与模型语料上对齐支撑集。扩展多语言时新行若热启动失败，会新增一批 glitch，审计要在续训后重跑。</p><h3 id="主动触发与被动统计" tabindex="-1">主动触发与被动统计 <a class="header-anchor" href="#主动触发与被动统计" aria-label="Permalink to &quot;主动触发与被动统计&quot;">​</a></h3><p>被动计数会漏掉「只在特定拼接下才出现」的符号。主动方法是：对每个罕见 id 构造以其为独立 token 的提示（前后加特殊边界，防止被更长合并吃掉），观察损失与生成是否发散。Land 与 Bartolo 的探测走的是欠训检测；与聊天注入测试是不同管道，但都应在发版清单里。</p><p><span class="marginnote">数字逐位切分会消灭一批「多位数字幽灵块」，同时让 <code>0</code>–<code>9</code> 变得极频，这是好事。不要把高频数位误判为 glitch 的反面就停止审计其他符号。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>嵌入更新 \\(\\propto\\) 该 id 出现次数。次数≈0 时，行停在初始化：若初始化与已训嵌入不在同一尺度，点积注意力会给它异常的 logits，softmax 要么塌成均匀要么塌成尖峰。生成时一旦采样到该 id，后续条件分布离开训练支撑，表现为重复、乱码或把训练数据残片吐出来。这是分布外离散符号，不是语义学到了「Magikarp」。</p><p><span class="marginnote">数字实例：普通 token 在一万亿 token 的预训练里可能出现几十亿次，而一个 glitch 出现 3 次——梯度更新量差约 9 个数量级。相当于别的词上了 9 年课，它一天课都没上过，考试（生成）时自然只会乱答。这也是「范数异常」能当检测信号的原因：没学过的向量长度和学过的长得不一样。</span></p>',8)),(e(),l(A,null,{default:E(()=>[r(i,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E8%AF%8D%E8%A1%A8%20V%22%5D%20--%3E%20ENC%5B%22%E6%A8%A1%E5%9E%8B%E8%AF%AD%E6%96%99%E4%B8%8A%E7%9A%84%E7%9C%9F%E5%AE%9E%E5%88%87%E5%88%86%22%5D%0A%20%20ENC%20--%3E%20CNT%5B%22id%20%E8%AE%A1%E6%95%B0%22%5D%0A%20%20CNT%20--%3E%20LOW%5B%22%E6%8E%A5%E8%BF%91%E9%9B%B6%E7%9A%84%20id%22%5D%0A%20%20LOW%20--%3E%20EMB%5B%22%E5%BC%82%E5%B8%B8%E5%B5%8C%E5%85%A5%E8%8C%83%E6%95%B0%22%5D%0A%20%20EMB%20--%3E%20GEN%5B%22%E8%A7%A6%E5%8F%91%E5%90%8E%E5%B4%A9%E6%BA%83%E7%94%9F%E6%88%90%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>审计扫不到的对抗拼接仍可能存在；过滤器不能替代把词表语料与模型语料对齐。把所有低频 id 都当 glitch 杀掉，会伤害真正的罕见专名。阈值必须结合范数与触发实验。下一单元开始改的是桶权重与文档选择，不再改 \\(V\\)；若 glitch 仍在，配比再精也只是更频繁地避开那些 id，病灶还在词表快照里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲平均 fertility；只补支撑集为空的那些 id。</li><li>glitch 来自词表测度与模型测度不一致、dummy 槽、以及从未插入的控制符。</li><li>用真实加载器计数 + 嵌入几何 + 主动触发做发版审计。</li><li>已发布模型不要重编号删除；用过滤与下一代词表修复。</li><li>出处：Rumbelow &amp; Watkins, SolidGoldMagikarp, 2023；Land &amp; Bartolo, <em>Fishing for Magikarp</em>, 2024。</li></ul>',4))])}const u=n(s,[["render",p]]);export{D as __pageData,u as default};
